import * as store from './store.js';
import {RM,today,monthNow,can,staff,admin,attendanceBalance,attendanceSummary,money,signedMoney,csv,bucket,valid,policy,plan,expectedFee,account as memberAccount,clubAccount,statement,cutoff,stockCount} from './domain.js';
const app=document.querySelector('#app'),dialog=document.querySelector('#dialog');
let user=null,data=null,page='Dashboard',filter='',financeTab='Planner',busy=false,year=Number(today().slice(0,4)),through=Number(today().slice(5,7));
const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const initials=n=>String(n||'?').split(' ').slice(0,2).map(s=>s[0]).join('').toUpperCase();
const icon=(name)=>{const paths={grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',wallet:'M3 6h18v15H3z M3 6V3h15v3 M16 12h5v5h-5z',users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M16 3a4 4 0 0 1 0 8 M22 21v-2a4 4 0 0 0-3-3.87 M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0',calendar:'M3 5h18v16H3z M16 3v4 M8 3v4 M3 11h18',chart:'M3 3v18h18 M7 16v-4 M12 16V7 M17 16v-7',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M12 2v3 M12 19v3 M2 12h3 M19 12h3 M5 5l2 2 M17 17l2 2 M19 5l-2 2 M7 17l-2 2',arrow:'M5 12h14 M13 6l6 6-6 6',clock:'M12 8v5l3 2 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',pin:'M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0 M15 10a3 3 0 1 1-6 0 3 3 0 0 1 6 0',check:'M5 12l4 4L19 6',file:'M14 2H4v20h16V8z M14 2v6h6 M8 13h8 M8 17h5',logout:'M9 3H3v18h6 M9 12h12 M17 8l4 4-4 4'};return `<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.grid}"/></svg>`;};
const tag=(text,kind='')=>`<span class="badge ${kind}">${escape(text)}</span>`;
const member=id=>data.members.find(m=>m.id===id)||{name:'Member',id};
const name=id=>escape(member(id).name);
const fin=()=>can(user,'finance'),act=()=>can(user,'activities'),owner=()=>admin(user),see=()=>staff(user);
const monthLabel=m=>new Date(m+'-01T12:00:00').toLocaleDateString('en-MY',{month:'short',year:'numeric'});
const dateLabel=d=>d?new Date(d+'T12:00:00').toLocaleDateString('en-MY',{day:'numeric',month:'short',year:'numeric'}):'—';
const sortDate=arr=>[...arr].sort((a,b)=>(b.date||'').localeCompare(a.date||''));
const stat=(label,value,sub,ico)=>`<div class="stat"><div class="stat-label"><span>${label}</span>${icon(ico)}</div><div class="value">${value}</div><small>${sub}</small></div>`;
function table(headers,rows,empty='No records yet.'){return rows.length?`<div class="table-wrap"><table><thead><tr>${headers.map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table></div>`:`<div class="empty">${empty}</div>`;}
const person=m=>`<div class="member-cell"><span class="avatar">${escape(initials(m.name))}</span><div><strong>${escape(m.name)}</strong><br><small>${escape(m.type==='adhoc'?'Ad hoc member':'Full member')}</small></div></div>`;
function toast(msg){const el=document.querySelector('#toast');el.textContent=msg;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),5500);}
function formError(err){const target=dialog.open?dialog.querySelector('.form-error'):document.querySelector('.form-error');if(target){target.textContent=err.message||String(err);target.hidden=false;}else toast(err.message||String(err));}
async function run(fn,message='Saved successfully.'){if(busy)return;busy=true;document.querySelectorAll('button[type=submit]').forEach(b=>b.disabled=true);try{await fn();dialog.close();await refresh();if(message)toast(message);}catch(e){formError(e);}finally{busy=false;document.querySelectorAll('button[type=submit]').forEach(b=>b.disabled=false);}}
async function refresh(){data=await store.load();user={...store.current(),verified:true};render();}
function loginScreen(mode='login'){
 const live=store.configured;
 app.innerHTML=`<div class="login"><section class="login-story"><div class="brand"><span class="brand-mark">S</span><div>Santai<small>BADMINTON CLUB</small></div></div><div><div class="eyebrow">YOUR CLUB. ONE PLACE.</div><h1>Good games.<br>Great company.<br>A club in sync.</h1><p>Keep up with club nights, settle your fees and see how our club is doing.</p></div><small>Santai Badminton Club · Member portal</small></section><section class="login-form"><div class="login-inner"><h1>${mode==='register'?'Join the club portal':'Welcome to Santai'}</h1><p>${live?'Sign in to your member account.':'Explore the club portal using sample records.'}</p>${live?`<form id="auth-form">${mode==='register'?'<label>Full name<input name="name" required maxlength="80" autocomplete="name"></label>':''}<label>Email address<input name="email" type="email" required autocomplete="email"></label><label>Password<input name="password" type="password" required minlength="10" autocomplete="${mode==='register'?'new-password':'current-password'}"></label><div class="form-error error" hidden></div><button class="primary" type="submit">${mode==='register'?'Create account':'Sign in'} ${icon('arrow')}</button></form><div class="row between" style="margin-top:16px"><button class="link" data-action="auth-mode" data-mode="${mode==='register'?'login':'register'}">${mode==='register'?'Already registered? Sign in':'Create a member account'}</button><button class="link" data-action="reset">Forgot password?</button></div>${mode==='register'?'<p class="form-help">Please verify your email. The owner must approve your membership before you can access club records.</p>':''}`:'<div class="notice">The live club database is not connected yet. Demo actions use sample data in this browser tab and reset when the page reloads.</div>'}<div class="login-footer"><button class="${live?'':'primary'}" data-action="demo">Explore demonstration ${icon('arrow')}</button><p class="form-help">Try owner, committee and member views.<br>No real payments or member records.</p></div></div></section></div>`;
 document.querySelector('#auth-form')?.addEventListener('submit',async e=>{e.preventDefault();if(busy)return;const d=new FormData(e.target);busy=true;e.submitter.disabled=true;try{if(mode==='register'){await store.register(d.get('name').trim(),d.get('email').trim(),d.get('password'));await store.logout();loginScreen();toast('Account created. Check your email, verify it, then sign in.');}else await store.login(d.get('email').trim(),d.get('password'));}catch(err){formError(err);}finally{busy=false;if(e.submitter)e.submitter.disabled=false;}});
}
function waiting(u){app.innerHTML=`<div class="login-form" style="min-height:100vh"><div class="login-inner"><h1>${!u.verified?'Verify your email':'Membership approval'}</h1><p>${escape(u.error||(!u.verified?'Open the verification email, then sign out and sign in again.':'Your account is awaiting the owner’s approval. If your access was suspended, contact the committee.'))}</p><div class="stack">${!u.verified?'<button data-action="resend">Resend verification email</button>':''}<button data-action="logout">Sign out</button></div></div></div>`;}
function nav(label,ico){return `<button class="nav-item ${page===label?'active':''}" data-page="${label}">${icon(ico)}${label}</button>`;}
const months=['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
const period=()=>year+'-'+String(through).padStart(2,'0');
const signed=n=>n>0?'+'+RM(n):RM(n);
const within=x=>x.date>=year+'-01-01'&&x.date<=cutoff(year,through);
const feeMode=p=>p.mode==='monthly'?`${Math.round(p.factor*10000)/100}% payable`:p.mode==='attendance'?'Per attendance':'Exempt';
const who=id=>id==='walkin'?'AhliMendatang':id.startsWith('guest_')?escape(data.guests.find(g=>g.id===id)?.name||'Guest')+' · AhliMendatang':name(id);
function periodPicker(){return `<div class="row"><label>Year<input id="report-year" type="number" min="2000" max="2100" value="${year}" style="width:100px"></label><label>${page==='Attendance summary'?'Month':'Through month'}<select id="report-month">${months.map((m,i)=>`<option value="${i+1}" ${through===i+1?'selected':''}>${m}</option>`).join('')}</select></label></div>`;}
function render(){app.innerHTML=`<div class="app-shell"><div class="menu-overlay" data-action="close-menu"></div><aside class="sidebar"><button class="mobile-close" data-action="close-menu" aria-label="Close menu">×</button><div class="brand"><span class="brand-mark">S</span><div>Santai<small>BADMINTON CLUB</small></div></div><div class="nav-label">CLUB SPACE</div>${nav('Dashboard','grid')}${nav('My account','wallet')}${nav('Courts & activities','calendar')}${nav('Attendance summary','users')}${nav('Member statements','file')}${see()?nav('Club finances','chart')+nav('Members','users'):''}${see()?nav('Shuttle stock','grid'):''}${see()?nav('Activity log','file'):''}${owner()?nav('Settings','settings'):''}<div class="sidebar-footer"><strong>Monday & Wednesday</strong>9–11 pm · Community badminton<br><button class="nav-item" data-action="logout">${icon('logout')}Sign out</button></div></aside><main class="main"><header class="topbar"><button class="mobile-menu" data-action="menu" aria-label="Open menu">☰</button><div class="breadcrumb">Club portal <span>/ ${escape(page)}</span></div><div class="row"><span class="avatar">${escape(initials(user.name))}</span><div class="user-name">${escape(user.name)}<div class="user-role">${escape(user.role)}</div></div><button class="small" data-action="refresh">Refresh</button></div></header>${store.isDemo()?`<div class="demo-bar"><span><strong>Demonstration</strong> · Fictional records · resets on reload</span><label class="row">View as <select id="demo-role">${[['owner','Owner'],['administrator','Administrator'],['finance','Fee collector'],['activities','Court coordinator'],['stock','Shuttle coordinator'],['member','Member']].map(([v,l])=>`<option value="${v}" ${user.id===({'owner':'demo-0','administrator':'demo-4','finance':'demo-1','activities':'demo-2','stock':'demo-3','member':'demo-22'}[v])?'selected':''}>${l}</option>`).join('')}</select></label></div>`:''}<div class="content"><div class="page-header"><div><h1>${escape(page)}</h1><p>${{'Dashboard':'Our club, on and off the court.','My account':'Your approved fee arrangements, credits and payment records.','Courts & activities':'Monday and Wednesday, 9–11 pm, except announced closures.','Club finances':'Yearly records · positive balance = credit; negative = arrears.','Member statements':'Committee-published PenyataAhli and Print statements.','Members':'Membership and volunteer responsibilities.','Shuttle stock':'Count in individual shuttlecocks; record tubes as their total contents.','Attendance summary':'Confirmed attendance for the selected month.','Activity log':'Club changes and responsible users.','Settings':'Club details and financial year controls.'}[page]}</p></div>${['Dashboard','My account','Club finances','Member statements','Attendance summary'].includes(page)?periodPicker():''}</div>${page==='Dashboard'?dashboard():page==='My account'?accountView():page==='Club finances'?finances():page==='Courts & activities'?activities():page==='Member statements'?publicStatements():page==='Members'?members():page==='Shuttle stock'?stockView():page==='Attendance summary'?summaryView():page==='Activity log'?auditView():owner()?settings():''}</div></main></div>`;
 document.querySelector('#demo-role')?.addEventListener('change',async e=>{user=store.startDemo(e.target.value);page='Dashboard';await refresh();});
 document.querySelector('#report-year')?.addEventListener('change',e=>{const v=Number(e.target.value);if(v>=2000&&v<=2100){year=v;render();}});document.querySelector('#report-month')?.addEventListener('change',e=>{through=Number(e.target.value);render();});document.querySelector('#member-search')?.addEventListener('input',e=>{filter=e.target.value;document.querySelector('#members-table').innerHTML=memberTable();});document.querySelector('#settings-form')?.addEventListener('submit',saveSettingsForm);
}
function chart(rows){if(!rows.some(r=>r.income||r.expense))return '<div class="empty">No cash movements in this period.</div>';const max=Math.max(1,...rows.flatMap(r=>[r.income,r.expense]));return `<div class="legend"><span><i></i>Received</span><span><i class="light"></i>Expenses</span></div><div class="chart">${rows.map(r=>`<div class="chart-group"><div class="bar" style="height:${Math.max(1,r.income/max*100)}%" title="${escape(r.name)} received ${RM(r.income)}"></div><div class="bar expense" style="height:${Math.max(1,r.expense/max*100)}%" title="${escape(r.name)} expenses ${RM(r.expense)}"></div></div>`).join('')}</div><div class="chart-labels">${rows.map(r=>`<span>${r.name}</span>`).join('')}</div>`;}
function latestPublication(){return data.publications.filter(p=>p.year===year&&p.month<=through).sort((a,b)=>a.month-b.month).at(-1);}
function openingPending(){return see()&&!(data.yearOpenings||[]).length&&(data.summaries||[]).some(s=>s.id==='all'&&s.opening);}
function openingWarning(){return openingPending()?'<div class="notice">Opening balance migration required: record the original club cash opening and its year under Planner → Opening balance before relying on the club cash total.</div>':'';}
function dashboard(){const s=see()?clubAccount(data,year,through):latestPublication();const mine=memberAccount(data,user.id,year,through),a=memberAccount(data,user.id,year,through,'attendance');const next=data.activities.filter(a=>a.date>=today()&&a.status!=='Cancelled'&&!policy(data,a.date.slice(0,7)).closed).sort((a,b)=>a.date.localeCompare(b.date)).slice(0,3);return `${openingWarning()}${data.settings.notice?`<div class="notice">${escape(data.settings.notice)}</div>`:''}<div class="stat-grid">${see()?stat('Club cash balance',openingPending()?'Review opening':RM(s.closing),'Opening funds + verified receipts − paid costs','wallet'):stat('My monthly balance',signed(mine.balance),'+ credit · − outstanding','wallet')}${stat(see()?'Receipts this year':'Published receipts',RM(see()?s.received:s?.income||0),see()?`Through ${months[through-1]} ${year}`:s?`Published through ${months[s.month-1]} ${s.year}`:'Awaiting committee publication','chart')}${stat(see()?'Expenses this year':'Published expenses',RM(s?.expenses||0),'Paid costs','file')}${stat(see()?'Year surplus / deficit':'My attendance balance',signed(see()?s.net:a.balance),see()?'Excludes opening funds':'+ credit · − outstanding','clock')}</div><div class="dashboard-columns"><section class="panel"><h2>Income & expenses</h2>${chart(Array.from({length:through},(_,i)=>({name:months[i],income:see()?data.payments.filter(p=>valid(p)&&p.date.startsWith(year+'-'+String(i+1).padStart(2,'0'))).reduce((s,p)=>s+p.amount,0):s?.totals[i]||0,expense:see()?data.expenses.filter(p=>valid(p)&&p.date.startsWith(year+'-'+String(i+1).padStart(2,'0'))).reduce((s,p)=>s+p.amount,0):s?.expenseRows.reduce((a,r)=>a+r.monthly[i],0)||0})))}</section><section class="panel"><h2>Next on court</h2>${next.map(a=>`<div class="session-card"><div class="date-box"><small>${months[Number(a.date.slice(5,7))-1]}</small><strong>${Number(a.date.slice(8))}</strong></div><div><h3>${escape(a.title)}</h3><p>${escape(a.time)}–${escape(a.end)} · ${escape(a.venue)}</p><p>Courts ${escape(a.courts)}</p></div></div>`).join('')||'<div class="empty">No upcoming sessions.</div>'}</section></div><section class="panel"><h2>Committee decisions</h2>${table(['Effective month','Monthly base','Per attendance','Closure / decision'],data.periods.sort((a,b)=>b.id.localeCompare(a.id)).map(p=>`<tr><td>${monthLabel(p.id)}</td><td>${RM(p.monthly)}</td><td>${RM(p.attendance)}</td><td>${p.closed?tag('Closed','amber')+' ':''}${escape(p.reason)}</td></tr>`))}</section>`;}
function accountView(){const a=memberAccount(data,user.id,year,through),b=memberAccount(data,user.id,year,through,'attendance'),p=plan(data,user,period());return `<div class="stat-grid">${stat('Monthly balance',signed(a.balance),'+ credit · − arrears','wallet')}${stat('Bawa ke hadapan',signed(a.opening),'Monthly account opening for '+year,'file')}${stat('Monthly fees issued',RM(a.assessed),'Paid this year '+RM(a.paid),'chart')}${stat('Attendance balance',signed(b.balance),'Attendance paid '+RM(b.paid),'users')}</div><div class="row" style="margin-bottom:22px"><button class="primary" data-action="submit-payment">Report payment / upload screenshot</button><button data-action="request-plan">Request fee arrangement</button><span class="badge">Permanent membership: ${user.type==='adhoc'?'No':'Yes'}</span><span class="badge">${escape(feeMode(p))}</span></div><div class="notice">Arrangements apply only to the selected month. Unset months are no fee/exempt. Payments can cover several months or build a credit. Attendance payments are recorded personally and grouped under AhliMendatang in shared statements.</div><section class="panel" style="margin-bottom:22px"><h2>Fees issued through ${months[through-1]} ${year}</h2>${chargeTable(data.charges.filter(c=>c.uid===user.id&&within(c)),false)}</section><section class="panel" style="margin-bottom:22px"><div class="panel-title"><h2>Verified payments</h2><button class="small" data-action="export-own">Download CSV</button></div>${paymentTable(data.payments.filter(p=>p.uid===user.id&&within(p)),false)}</section><div class="grid2"><section class="panel"><h2>Payment submissions</h2>${submissionTable(data.submissions.filter(s=>s.uid===user.id),false)}</section><section class="panel"><h2>Fee requests</h2>${requestTable(data.requests.filter(r=>r.uid===user.id),false)}</section></div>`;}
function chargeTable(rows,staff){return table([...(staff?['Member']:[]),'Fee date','Description','Type','Amount',''],sortDate(rows).map(c=>`<tr>${staff?`<td>${who(c.uid)}</td>`:''}<td>${dateLabel(c.date)}</td><td>${escape(c.label)}${c.correctionReason?'<br><small>'+escape(c.correctionReason)+'</small>':''}</td><td>${bucket(c)==='attendance'?'Attendance':'Monthly'}</td><td class="numeric">${RM(c.amount)}</td><td></td></tr>`));}
function paymentTable(rows,staff){return table(['Date',...(staff?['Member / guest']:[]),'Account','Reference','Amount',''],sortDate(rows).map(p=>`<tr><td>${dateLabel(p.date)}</td>${staff?`<td>${p.uid.startsWith('guest_')?'AhliMendatang':who(p.uid)}${p.guestName?'<br><small>'+escape(p.guestName)+'</small>':''}</td>`:''}<td>${bucket(p)==='attendance'?'AhliMendatang'+(!p.attendanceId?' · unallocated':''):'Monthly'}${p.voidedAt?'<br>'+tag('Reversed','red'):''}</td><td>${escape(p.reference)}</td><td class="numeric">${RM(p.amount)}</td><td>${p.proofId?`<button class="small" data-action="proof" data-id="${escape(p.proofId)}">Screenshot</button>`:''} <button class="link small" data-action="receipt" data-id="${escape(p.id)}">Receipt</button>${fin()&&!p.voidedAt?` <button class="link small danger" data-action="reverse-payment" data-id="${escape(p.id)}">Reverse</button>`:''}</td></tr>`));}
function submissionTable(rows,staff,editable=staff){return table(['Date',...(staff?['Member']:[]),'Amount','Status',''],sortDate(rows).map(s=>`<tr><td>${dateLabel(s.date)}</td>${staff?`<td>${who(s.uid)}</td>`:''}<td>${RM(s.amount)}<br><small>${escape(s.reference)}</small></td><td>${tag(s.status,s.status==='pending'?'amber':s.status==='approved'?'green':'red')}${s.reason?'<br>'+escape(s.reason):''}</td><td>${s.proofId?`<button class="small" data-action="proof" data-id="${escape(s.proofId)}">Screenshot</button>`:''}${editable&&s.status==='pending'?` <button class="small" data-action="approve" data-id="${escape(s.id)}">Verify</button> <button class="link small" data-action="reject" data-id="${escape(s.id)}">Reject</button>`:''}</td></tr>`));}
function requestTable(rows,staff,editable=staff){return table([...(staff?['Member']:[]),'From','Requested arrangement','Status',''],rows.map(r=>`<tr>${staff?`<td>${who(r.uid)}</td>`:''}<td>${monthLabel(r.month)}</td><td>${escape(feeMode(r))}<br><small>${escape(r.reason)}</small></td><td>${tag(r.status)}</td><td>${editable&&r.status==='pending'?`<button class="small" data-action="review-plan" data-id="${escape(r.id)}">Review</button> <button class="link small" data-action="reject-plan" data-id="${escape(r.id)}">Reject</button>`:''}</td></tr>`));}
function planner(){const rows=data.members;return `<div class="row between" style="margin-bottom:20px"><h2>Planner ${year}</h2>${fin()?'<div class="row"><button data-action="period">Rates / closure</button><button data-action="opening">Opening balance</button></div>':''}</div><p class="form-help">Every unset month is — / no fee. Edit a cell to save that month's fee and update its balance immediately. Other months stay unchanged. A = attendance. Existing historical charges are retained.</p>${table(['Member',...months,'B/F','Fees to cutoff','Paid to cutoff','+/−'],rows.map(m=>{const a=memberAccount(data,m.id,year,through);return `<tr><td>${escape(m.name)}</td>${months.map((_,i)=>{const mo=year+'-'+String(i+1).padStart(2,'0'),p=plan(data,m,mo),c=data.charges.find(c=>c.uid===m.id&&c.month===mo&&c.kind==='monthly');const value=p.mode==='attendance'?'A':c?.amount?RM(c.amount):p.mode==='monthly'?RM(expectedFee(data,m,mo)):'—';return `<td>${fin()?`<button class="link small" data-action="plan" data-id="${escape(m.id)}" data-month="${mo}">${value}</button>`:value}</td>`;}).join('')}<td>${signed(a.opening)}</td><td>${RM(a.assessed)}</td><td>${RM(a.paid)}</td><td>${tag(signed(a.balance),a.balance<0?'red':'green')}</td></tr>`;}))}`;}
function attendancePayments(){const rows=data.charges.filter(c=>bucket(c)==='attendance'&&within(c));return `<h2>Attendance fees · settled and pending</h2>${table(['Date','Participant','Fee','Paid','Pending / credit',''],sortDate(rows).map(c=>{const key=c.attendanceId||c.id.replace(/^adhoc_/,''),v=attendanceBalance(data,key);return `<tr><td>${dateLabel(c.date)}</td><td>${c.guestName?escape(c.guestName)+' · AhliMendatang':who(c.uid)}</td><td>${RM(v.due)}</td><td>${RM(v.paid)}</td><td>${v.credit?tag(RM(v.credit)+' credit','green'):v.pending?tag(RM(v.pending)+' pending','amber'):tag('Settled','green')}</td><td>${fin()&&v.pending?`<button class="small" data-action="attendance-pay" data-id="${escape(key)}">Record payment</button>`:''}</td></tr>`;}))}<p class="form-help">Each attendance payment is linked to its session. Older unallocated receipts are shown below and need reconciliation; they are not assumed to settle a particular visit. Partial payments are supported. Overpayments caused by attendance corrections remain visible as credits.</p>`;}
function expenseTable(){return table(['Date','Category','Description','Reference','Amount',''],sortDate(data.expenses.filter(within)).map(e=>`<tr><td>${dateLabel(e.date)}</td><td>${escape(e.category)}</td><td>${escape(e.description)}${e.voidedAt?tag('Reversed','red'):''}</td><td>${escape(e.reference)}</td><td>${RM(e.amount)}</td><td>${e.proofId?`<button class="small" data-action="expense-proof" data-id="${escape(e.proofId)}">Vendor receipt</button>`:''}${fin()&&!e.voidedAt?`<button class="link small" data-action="reverse-expense" data-id="${escape(e.id)}">Reverse</button>`:''}</td></tr>`));}
function finances(){if(!see())return '';const c=clubAccount(data,year,through);return `${openingWarning()}<div class="stat-grid">${stat('Opening club funds',openingPending()?'Review opening':RM(c.opening),'Carried into '+year,'wallet')}${stat('Verified receipts',RM(c.received),'Through '+months[through-1],'chart')}${stat('Paid expenses',RM(c.expenses),'Through '+months[through-1],'file')}${stat('Closing club cash',openingPending()?'Review opening':RM(c.closing),'Opening + income − expenses','wallet')}</div>${fin()?'<div class="row" style="margin-bottom:16px"><button class="primary" data-action="payment">+ Record payment</button><button data-action="expense">+ Expense</button><button data-action="publish">Preview / publish statements</button></div>':'<p class="notice">Read-only financial access. Changes are assigned to the fee collector.</p>'}<div class="tabs">${['Planner','Payment Summary','Payment','Expenses','Payment Verification','Fee Request Verification'].map(t=>`<button data-tab="${t}" class="${financeTab===t?'active':''}">${t}</button>`).join('')}</div><section class="panel">${financeTab==='Planner'?planner():financeTab==='Payment Summary'?'<p class="form-help">Current calculated PenyataAhli. Members see the last published snapshot.</p>'+statementHTML(statement(data,year,through),false):financeTab==='Payment'?attendancePayments()+paymentTable(data.payments.filter(within),true):financeTab==='Expenses'?expenseTable():financeTab==='Payment Verification'?submissionTable(data.submissions,true,fin()):requestTable(data.requests,true,fin())}</section>`;}
function statementHTML(s,includePrint=true){return `<div class="statement-print"><h2>PenyataAhli · ${months[s.month-1]} ${s.year}</h2><p class="form-help">Payments shown by receipt month. Positive balance = credit; negative = arrears. AhliMendatang includes all attendance payments, including those from permanent members.</p>${table(['Name','B/F',...months.slice(0,s.month),'Fees issued','Paid','+/−'],s.rows.map(r=>`<tr><td>${escape(r.name)}</td><td>${signed(r.opening)}</td>${r.monthly.slice(0,s.month).map(n=>`<td>${n?RM(n):'—'}</td>`).join('')}<td>${RM(r.assessed)}</td><td>${RM(r.paid)}</td><td>${signed(r.balance)}</td></tr>`).concat([`<tr><td>AhliMendatang</td><td>—</td>${s.attendance.slice(0,s.month).map(n=>`<td>${n?RM(n):'—'}</td>`).join('')}<td>—</td><td>${RM(s.attendance.reduce((a,b)=>a+b,0))}</td><td>—</td></tr>`]))}<div class="row" style="margin:20px 0"><strong>Income ${RM(s.income)}</strong><strong>Expenses ${RM(s.expenses)}</strong><strong>Current-year surplus / deficit ${signed(s.net)}</strong></div><p class="form-help">This member report excludes the club’s opening funds and bank/cash balance.</p>${table(['Expenses',...months.slice(0,s.month),'Total'],s.expenseRows.map(r=>`<tr><td>${escape(r.category)}</td>${r.monthly.slice(0,s.month).map(n=>`<td>${n?RM(n):'—'}</td>`).join('')}<td>${RM(r.monthly.reduce((a,b)=>a+b,0))}</td></tr>`))} ${includePrint?`<h2 style="margin-top:28px">Print · Kurang / Lebih Bayar</h2>${table(['Member','Credit (+) / arrears (−)'],s.rows.map(r=>`<tr><td>${escape(r.name)}</td><td>${tag(signed(r.balance),r.balance<0?'red':r.balance>0?'green':'')}</td></tr>`))}`:''}</div>`;}
function publicStatements(){const s=data.publications.find(p=>p.year===year&&p.month===through);return `<section class="panel"><div class="panel-title"><h2>Shared with members</h2>${s?'<div class="row"><button data-action="print">Print / save PDF</button><button data-action="export-statement">Download CSV</button></div>':''}</div>${s?`<p class="form-help">Published ${new Date(s.publishedAt).toLocaleString('en-MY',{timeZone:'Asia/Kuala_Lumpur'})}. This is a snapshot; later changes appear after the committee republishes.</p>${statementHTML(s)}`:'<div class="empty">No member statement published for this period. Choose another year/month or ask the fee collector to publish it.</div>'}</section>`;}
function activities(){return `<div class="row" style="margin-bottom:20px">${act()?'<button class="primary" data-action="schedule-month">Create monthly court schedule</button><button data-action="activity">+ Activity / friendly / tournament</button>':''}</div><div class="activity-grid">${[...data.activities].sort((a,b)=>b.date.localeCompare(a.date)).map(a=>{const closed=policy(data,a.date.slice(0,7)).closed,r=data.rsvps.find(r=>r.activityId===a.id&&r.uid===user.id);return `<section class="panel activity-card"><div class="row between">${tag(a.kind,'green')}${tag(a.status==='Cancelled'?'Cancelled':closed?'Club closed':a.status==='Planned'?'Scheduled':a.status,a.status==='Cancelled'?'cancelled':closed?'amber':'')}</div><h2>${escape(a.title)}</h2><p>${dateLabel(a.date)} · ${escape(a.time)}–${escape(a.end)}</p><p>${escape(a.venue)} · Courts ${escape(a.courts)}</p><p class="form-help">${escape(a.notes)}</p>${a.results?`<div class="notice">${escape(a.results).replaceAll('\n','<br>')}</div>`:''}<div class="row">${!closed&&!['Cancelled','Completed'].includes(a.status)?`<button class="small ${r?.status==='going'?'primary':''}" data-action="rsvp" data-id="${escape(a.id)}" data-status="${r?.status==='going'?'not-going':'going'}">${r?.status==='going'?'Going · cancel':'I’m interested'}</button>`:''}${act()?`<button class="small" data-action="activity" data-id="${escape(a.id)}">Edit / results</button>${a.status!=='Cancelled'?`<button class="small danger" data-action="cancel-event" data-id="${escape(a.id)}">Cancel event</button>`:''}`:''}${see()?`<button class="small" data-action="attendance" data-id="${escape(a.id)}">Attendance</button>`:''}</div>${see()?`<p class="form-help">Attendance recorded: ${data.attendance.filter(x=>x.activityId===a.id).length}</p>`:''}</section>`;}).join('')||'<div class="panel empty">No activities yet.</div>'}</div>`;}
function members(){return `<div class="toolbar"><input id="member-search" type="search" placeholder="Search name or email…" aria-label="Search members"><span class="form-help">Membership and payment arrangement are managed separately.</span></div><section class="panel" id="members-table">${memberTable()}</section>`;}
function memberTable(){return table(['Member','Membership','Role / responsibilities','Status',''],data.members.filter(m=>(m.name+' '+m.email).toLowerCase().includes(filter.toLowerCase())).map(m=>`<tr><td><strong>${escape(m.name)}</strong><br><small>${escape(m.email)}</small></td><td>${m.type==='adhoc'?'Registered attendance member':'Permanent'}</td><td>${escape(m.role)}<br><small>${escape((m.permissions||[]).join(', '))}${m.role==='committee'?'<br>'+(m.termUntil?'Optional term end: '+dateLabel(new Date(m.termUntil).toISOString().slice(0,10)):'Until withdrawn / replaced'):''}</small></td><td>${tag(m.status)}</td><td>${owner()&&(user.role==='owner'||!['owner','administrator'].includes(m.role))?`<button class="small" data-action="member" data-id="${escape(m.id)}">Manage</button>`:''}</td></tr>`));}
function stockView(){const n=stockCount(data);return `<div class="stat-grid">${stat('Available shuttlecocks',n,'Recorded stock movements','grid')}${stat('Low-stock threshold',data.settings.stockThreshold??24,n<=(data.settings.stockThreshold??24)?'Replenishment needed':'Stock above threshold','clock')}</div><div class="row" style="margin-bottom:20px">${can(user,'stock')?'<button class="primary" data-action="stock">Record stock movement</button>':''}</div><section class="panel">${table(['Date','Type','In / out','Notes'],sortDate(data.stock).map(s=>`<tr><td>${dateLabel(s.date)}</td><td>${escape(s.kind)}</td><td>${s.quantity>0?'+':''}${s.quantity}</td><td>${escape(s.notes)}</td></tr>`))}<p class="form-help">Stock receipts do not record an expense automatically. The fee collector records the supplier payment separately to avoid double-counting.</p></section>`;}
function settings(){const s=data.settings;return `<div class="grid2"><section class="panel"><h2>Club details</h2><form id="settings-form" class="stack"><label>Announcement<textarea name="notice" maxlength="1000">${escape(s.notice)}</textarea></label>${field('Bank','bankName','text',s.bankName,'maxlength="100"')}${field('Account holder','accountName','text',s.accountName,'maxlength="100"')}${field('Account number','accountNumber','text',s.accountNumber,'maxlength="40"')}<label>Bank QR image<input name="qr" type="file" accept="image/png,image/jpeg,image/webp"></label>${s.qrData?`<img src="${escape(s.qrData)}" class="qr" alt="Club payment QR">`:''}${field('Shuttle low-stock threshold (individual shuttles)','stockThreshold','number',s.stockThreshold??24,'min="0" max="10000" required')}<div class="form-error error" hidden></div><button class="primary" type="submit">Save settings</button></form></section><div class="stack"><section class="panel"><h2>Public attendance roster</h2><p class="form-help">After upgrading, synchronise the name-only roster so existing members appear in the monthly attendance summary, including zero attendance. New membership approvals update it automatically.</p><button data-action="sync-roster">Synchronise registered roster</button></section><section class="panel"><h2>Financial years</h2><p class="form-help">Credit, arrears and club cash roll forward from prior records. Closing a year blocks financial changes; reopen it explicitly to correct records, then review and republish affected later statements.</p><button data-action="year-lock">Close / reopen year</button><p>${data.yearLocks.map(y=>escape(y.id)+': '+(y.closed?'closed':'open')).join('<br>')||'No years closed yet.'}</p></section><section class="panel"><h2>Private backup</h2><p class="form-help">Includes financial data and payment screenshots. Save securely on your computer, outside the public code repository.</p><button data-action="backup">Download full JSON backup</button></section></div><section class="panel full-width"><h2>Recent application activity</h2>${table(['Time','Actor','Action'],[...data.audit].sort((a,b)=>b.at-a.at).slice(0,40).map(a=>`<tr><td>${new Date(a.at).toLocaleString('en-MY')}</td><td>${who(a.actor)}</td><td>${escape(a.action)}</td></tr>`))}</section></div>`;}
function modal(title,body,onSubmit,submit='Save'){dialog.innerHTML=`<div class="modal-header"><h2>${escape(title)}</h2><button type="button" data-action="close-dialog" aria-label="Close dialog">×</button></div><form id="modal-form">${body}<div class="form-error error" hidden></div><div class="actions"><button type="button" data-action="close-dialog">Cancel</button>${onSubmit?`<button class="primary" type="submit">${escape(submit)}</button>`:''}</div></form>`;dialog.showModal();if(onSubmit)dialog.querySelector('form').addEventListener('submit',e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));run(()=>onSubmit(d));});}
const field=(label,key,type='text',value='',extra='')=>`<label>${label}<input name="${key}" type="${type}" value="${escape(value)}" ${extra}></label>`;
const select=(label,key,choices,value)=>`<label>${label}<select name="${key}">${choices.map(([v,l])=>`<option value="${escape(v)}" ${v===value?'selected':''}>${escape(l)}</option>`).join('')}</select></label>`;
function bindProofPreview(){const input=dialog.querySelector('[name=proof]');input?.addEventListener('change',async()=>{try{const image=await store.compressProof(input.files[0]);const preview=dialog.querySelector('#proof-preview');preview.src=image;preview.hidden=!image;}catch(e){formError(e);}});}
function paymentModal(submit=false,attendanceId=''){const s=data.settings,c=attendanceId?data.charges.find(c=>c.id==='adhoc_'+attendanceId):null;const charges=data.charges.filter(c=>bucket(c)==='attendance'&&c.amount>0&&(!submit||c.uid===user.id));modal(submit?'Report a payment':'Record a verified payment',`${submit?`<div class="payment-box">${s.qrData?`<img src="${escape(s.qrData)}" class="qr" alt="Club bank QR">`:'<p>The committee has not added the payment QR yet.</p>'}<strong>${escape(s.bankName)}</strong><p>${escape(s.accountName)}<br>${escape(s.accountNumber)}</p><small>Complete the transfer in your banking app, then submit its confirmation.</small></div>`:select('Member (for monthly payments)','uid',data.members.map(m=>[m.id,m.name]),c?.uid||user.id)}${select('Payment account','bucket',[['monthly','Monthly membership / advance'],['attendance','Attendance · AhliMendatang']],attendanceId?'attendance':'monthly')}${select('Attendance being paid (required for attendance account)','attendanceId',[['','Select a session'],...charges.map(c=>[c.attendanceId||c.id.replace(/^adhoc_/,''),dateLabel(c.date)+' · '+(c.guestName||member(c.uid).name)+' · '+RM(c.amount)])],attendanceId)}<div class="grid2">${field('Amount (RM)','amount','number',attendanceId?attendanceBalance(data,attendanceId).pending/100:'','required min="0.01" max="100000" step="0.01"')}${field('Payment date','date','date',today(),`required max="${today()}"`)}</div>${select('Method','method',[['Bank transfer','Bank transfer'],['Cash','Cash']],'Bank transfer')}${field('Bank transaction / cash receipt reference','reference','text','','required maxlength="100"')}<label>Successful payment screenshot (optional)<input name="proof" type="file" accept="image/png,image/jpeg,image/webp"></label><p class="form-help">Attendance payments settle the selected session for its named person. Split one transfer across its sessions using the same reference. Screenshots are visible to their owner and all committee members. Only finance verifies receipt.</p><img id="proof-preview" hidden style="max-width:100%;max-height:280px;object-fit:contain" alt="Compressed screenshot preview">`,async d=>{const linked=d.bucket==='attendance'?data.charges.find(c=>c.id==='adhoc_'+d.attendanceId):null;if(d.bucket==='attendance'&&!linked)throw Error('Select an attendance session.');const payload={uid:linked?linked.uid:submit?user.id:d.uid,bucket:d.bucket,attendanceId:linked?d.attendanceId:'',amount:money(d.amount),date:d.date,reference:d.reference.trim(),method:d.method,guestName:linked?.guestName||''};if(submit&&payload.uid!==user.id)throw Error('Select your own attendance.');const image=await store.compressProof(d.proof);return submit?store.submitPayment(payload,image):store.recordPayment(payload,null,image);},submit?'Submit for verification':'Confirm received');bindProofPreview();}
function planModal(uid,mo=period(),requestId=null){const m=member(uid),req=data.requests.find(r=>r.id===requestId),p=req||plan(data,m,mo),charge=data.charges.find(c=>c.uid===uid&&c.kind==='monthly'&&c.month===mo);modal(requestId?'Review fee request':'Edit Planner month',`<p><strong>${escape(m.name)}</strong> · ${monthLabel(mo)}</p>${select('Arrangement','mode',[['exempt','No fee / exempt'],['monthly','Monthly fee'],['attendance','Pay per attendance']],p.mode)}${field('Monthly fee (RM)','amount','number',req?Math.round(policy(data,mo).monthly*p.factor)/100:charge?charge.amount/100:expectedFee(data,m,mo)/100,'required min="0" max="100000" step="0.01"')}<p class="form-help">Only ${monthLabel(mo)} changes. No fee/exempt and attendance set the monthly fee to RM0. Existing attendance charges and cash payments are unchanged. Other months do not inherit this choice.</p>${field('Approval / correction reason','reason','text',req?.reason||'','required maxlength="300"')}`,d=>{const amount=d.mode==='monthly'?money(d.amount,true):0;return store.savePlan(uid,{month:mo,mode:d.mode,amount,factor:Math.min(1,amount/(policy(data,mo).monthly||1)),reason:d.reason},requestId);});}
function requestModal(){modal('Request a fee arrangement',`${field('Selected month','month','month',period(),'required')}${select('Requested payment method','mode',[['monthly','Monthly fee, full or discounted'],['attendance','Per attendance'],['exempt','Exemption']], 'monthly')}${field('Monthly base payable (%)','percent','number','100','required min="0" max="100" step="0.01"')}${field('Reason','reason','text','','required maxlength="300"')}<p class="form-help">The committee must approve the change. This applies only to the selected month. Membership status remains unchanged.</p>`,d=>store.requestPlan({month:d.month,mode:d.mode,factor:Number(d.percent)/100,reason:d.reason}),'Send request');}
function memberModal(key){const m=member(key);modal('Manage '+m.name,`${field('Name','name','text',m.name,'required maxlength="80"')}${select('Membership group','type',[['full','Permanent member'],['adhoc','Registered attendance member']],m.type)}${select('Access status','status',[['pending','Pending approval'],['active','Active'],['suspended','Withdrawn / suspended']],m.status)}${m.role==='owner'?'<p>This is the owner account.</p>':`${select('Role','role',[['member','Member'],['committee','Volunteer committee'],...(user.role==='owner'?[['administrator','Administrator']]:[])],m.role)}<p class="form-help">Committee appointments continue until withdrawn or replaced. Leave the optional end date blank for an ongoing appointment.</p>${field('Optional end date','term','date',m.termUntil?new Date(m.termUntil).toISOString().slice(0,10):'')}${[['finance','Fee collection and financial records'],['activities','Court bookings, schedules and activities'],['stock','Shuttle stock and replenishment']].map(([v,l])=>`<label class="check"><input type="checkbox" name="${v}" ${m.permissions?.includes(v)?'checked':''}>${l}</label>`).join('')}`}`,d=>store.saveMember(key,{name:d.name.trim(),type:d.type,status:d.status,role:m.role==='owner'?'owner':d.role,permissions:d.role==='committee'?['finance','activities','stock'].filter(p=>d[p]):[],termUntil:d.role==='committee'&&d.term?new Date(d.term+'T23:59:59+08:00').getTime():0}));}
function activityModal(key){const a=data.activities.find(a=>a.id===key)||{date:today(),time:'21:00',end:'23:00',capacity:30,cost:0,status:'Scheduled',kind:'Club session'};modal(key?'Edit activity':'Add club activity',`${field('Title','title','text',a.title,'required maxlength="100"')}${select('Type','kind',['Club session','Internal tournament','Friendly match'].map(x=>[x,x]),a.kind)}${select('Status','status',['Planned','Scheduled','Completed','Cancelled'].map(x=>[x,x]),a.status)}${field('Date','date','date',a.date,'required')}<div class="grid2">${field('Start (Malaysia)','time','time',a.time,'required')}${field('End (Malaysia)','end','time',a.end,'required')}</div>${field('Venue','venue','text',a.venue,'required maxlength="160"')}${field('Courts','courts','text',a.courts,'maxlength="60"')}${field('Capacity','capacity','number',a.capacity,'required min="1" max="200"')}${field('Estimated cost (RM)','cost','number',a.cost/100,'required min="0" max="100000" step="0.01"')}<label>Notes / opponent / booking reference<textarea name="notes" maxlength="2000">${escape(a.notes)}</textarea></label><label>Draw / scores / results<textarea name="results" maxlength="4000">${escape(a.results)}</textarea></label>`,d=>{if(d.end<=d.time)throw Error('End must be after start.');return store.saveActivity(key||null,{...d,cost:money(d.cost,true),capacity:Number(d.capacity)});});}
const attendanceMark=status=>status==='present'?'<span class="attendance-present" aria-label="Present">✓</span>':status==='absent'?'<span class="attendance-absent" aria-label="Absent">×</span>':'';
function attendanceModal(key){const a=data.activities.find(a=>a.id===key),uids=new Set([...data.members.filter(m=>m.status==='active').map(m=>m.id),...data.attendance.filter(x=>x.activityId===key).map(x=>x.uid),...data.attendanceDrafts.filter(x=>x.activityId===key).map(x=>x.uid)]);const row=uid=>{const g=data.guests.find(g=>g.id===uid),r=data.rsvps.find(x=>x.activityId===key&&x.uid===uid),d=data.attendanceDrafts.find(x=>x.activityId===key&&x.uid===uid),f=data.attendance.find(x=>x.activityId===key&&x.uid===uid);return `<tr><td>${g?escape(g.name):name(uid)}</td><td class="attendance-cell">${attendanceMark(f?.status)}</td><td class="attendance-controls">${r?.status==='going'?tag('Interested','green'):r?.status==='not-going'?'Not attending':''}${d?'<small>Proposal: '+escape(d.status)+'</small>':''}<button type="button" class="small" data-action="attendance-edit" data-id="${escape(key)}" data-uid="${escape(uid)}">${act()?'Confirm / edit':'Propose change'}</button></td></tr>`;};modal('Attendance sheet',`<div class="attendance-sheet"><div class="row between"><p><strong>Date:</strong> ${dateLabel(a.date)}<br>${escape(a.title)}</p>${tag(a.status,a.status==='Cancelled'?'cancelled':'')}<button type="button" class="attendance-controls" data-action="print">Print / save PDF</button></div><p class="form-help attendance-controls">✓ Present · × Absent · blank Unconfirmed. Interest and proposals do not confirm attendance. The court coordinator makes the final decision.</p><h3>Registered members</h3>${table(['Members','Attendance','<span class="attendance-controls">Interest / committee action</span>'],[...uids].filter(uid=>!uid.startsWith('guest_')).map(row))}<h3 style="margin-top:24px">AhliMendatang</h3>${table(['Participants','Attendance','<span class="attendance-controls">Interest / committee action</span>'],[...uids].filter(uid=>uid.startsWith('guest_')).map(row),'No walk-in participants recorded for this event.')}${a.status!=='Cancelled'?`<button type="button" class="attendance-controls" data-action="add-guest" data-id="${escape(key)}">+ AhliMendatang / walk-in</button>`:''}</div>`,null);dialog.classList.add('wide-dialog');}
function summaryView(){const s=attendanceSummary(data,period()),row=r=>`<tr><td>${escape(r.name)}</td>${s.events.map(e=>`<td class="attendance-cell" title="${escape(e.title)} · ${dateLabel(e.date)}">${e.status==='Cancelled'?'':attendanceMark(r.marks[e.id])}</td>`).join('')}<td class="attendance-cell">${r.total}</td></tr>`,headers=['Members / date',...s.events.map(e=>`<span title="${escape(e.title)} · ${dateLabel(e.date)}">${Number(e.date.slice(8))}${e.status==='Cancelled'?' (C)':''}</span>`),'Total'];const occasional=s.events.map(e=>s.occasionalGuests.reduce((n,g)=>n+Number(g.sessions.includes(e.id)),0));return `<section class="panel attendance-sheet"><div class="panel-title"><h2>Attendance summary · ${monthLabel(period())}</h2><button data-action="print">Print / save PDF</button></div><p class="form-help">✓ Present · × Absent · blank Unconfirmed · C Cancelled (excluded from totals). Guests with 4 or more confirmed visits are named under AhliMendatang. Other guest visits are combined.</p><h3>Registered members</h3>${table(headers,s.registered.map(row))}<h3 style="margin-top:24px">AhliMendatang</h3>${table(headers,s.regularGuests.map(row).concat(s.occasionalGuests.some(g=>g.total)?[`<tr><td>Other walk-in participants (count)</td>${occasional.map(n=>`<td class="attendance-cell">${n||''}</td>`).join('')}<td class="attendance-cell">${occasional.reduce((a,b)=>a+b,0)}</td></tr>`]:[]))}</section>`;}
function auditView(){return `<section class="panel">${table(['Time','Actor','Action'],[...data.audit].sort((a,b)=>b.at-a.at).slice(0,100).map(a=>`<tr><td>${new Date(a.at).toLocaleString('en-MY')}</td><td>${who(a.actor)}</td><td>${escape(a.action)}</td></tr>`))}</section>`;}
function download(filename,content,type='text/csv;charset=utf-8'){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([type.startsWith('text/csv')?'\uFEFF':'',content],{type}));a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),5000);}
async function saveSettingsForm(e){e.preventDefault();const d=new FormData(e.target);run(async()=>{const file=d.get('qr'),qrData=file?.size?await store.compressProof(file):data.settings.qrData||'';await store.saveSettings({notice:d.get('notice'),bankName:d.get('bankName'),accountName:d.get('accountName'),accountNumber:d.get('accountNumber'),qrData,stockThreshold:Number(d.get('stockThreshold'))});});}
app.addEventListener('click',handleClick);dialog.addEventListener('click',handleClick);
async function handleClick(e){const b=e.target.closest('button,[data-action]');if(!b)return;const action=b.dataset.action,key=b.dataset.id;try{
 if(b.dataset.page){page=b.dataset.page;render();window.scrollTo(0,0);return;}if(b.dataset.tab){financeTab=b.dataset.tab;render();return;}
 if(action==='close-dialog'){dialog.close();return;}if(action==='demo'){user=store.startDemo();page='Dashboard';await refresh();return;}if(action==='logout'){await store.logout();user=null;data=null;page='Dashboard';loginScreen();return;}
 if(action==='auth-mode'){loginScreen(b.dataset.mode);return;}if(action==='reset'){const email=document.querySelector('[name=email]')?.value;if(!email)throw Error('Enter your email first.');await store.reset(email);toast('Check your email for a reset link if the account exists.');return;}if(action==='resend'){await store.resend();toast('Verification email sent.');return;}
 if(action==='menu'||action==='close-menu'){document.querySelector('.sidebar')?.classList.toggle('open',action==='menu');document.querySelector('.menu-overlay')?.classList.toggle('visible',action==='menu');return;}if(action==='refresh'){await refresh();toast('Updated.');return;}
 if(action==='payment'||action==='submit-payment'){paymentModal(action==='submit-payment');return;}if(action==='request-plan'){requestModal();return;}if(action==='plan'){planModal(key,b.dataset.month);return;}if(action==='review-plan'){const r=data.requests.find(r=>r.id===key);planModal(r.uid,r.month,key);return;}if(action==='reject-plan'){modal('Reject fee request',field('Reason','reason','text','','required maxlength="300"'),d=>store.rejectRequest(key,d.reason),'Reject');return;}
 if(action==='member'){memberModal(key);return;}if(action==='activity'){activityModal(key);return;}if(action==='attendance'){attendanceModal(key);return;}if(action==='rsvp'){await run(()=>store.rsvp(key,b.dataset.status),'RSVP updated. Places are confirmed by the committee.');return;}
 if(action==='sync-roster'){await run(()=>store.syncRoster());return;}
 if(action==='cancel-event'){const a=data.activities.find(a=>a.id===key);modal('Cancel event',`<p>Cancel ${escape(a.title)} on ${dateLabel(a.date)}? Interest will be disabled. Existing attendance fees remain until deliberately corrected on the attendance sheet.</p>`,()=>{const {id,...entry}=a;return store.saveActivity(key,{...entry,status:'Cancelled'});},'Cancel event');return;}
 if(action==='attendance-edit'){dialog.close();const uid=b.dataset.uid,f=data.attendance.find(x=>x.activityId===key&&x.uid===uid);modal(act()?'Confirm attendance':'Propose attendance',`${select('Attendance','status',[['present','Present'],['absent','Absent']],f?.status||'present')}<p class="form-help">${act()?'Saving updates final attendance and its attendance fee. Payments remain recorded; any resulting credit is shown in Payment.':'The court coordinator must confirm your proposal.'}</p>`,d=>act()?store.confirmAttendance(key,uid,d.status):store.proposeAttendance(key,uid,d.status));return;}
 if(action==='add-guest'){dialog.close();modal('Add AhliMendatang participant',`${select('Returning guest','guest',[['','New guest'],...data.guests.map(g=>[g.id,g.name])],'')}${field('New guest name (leave blank for returning guest)','guestName','text','','maxlength="80"')}<p class="form-help">Choose the same guest on repeat visits. No login account is created. The court coordinator confirms attendance.</p>`,async d=>{const uid=d.guest||await store.saveGuest(d.guestName);return store.proposeAttendance(key,uid,'present');});return;}
 if(action==='attendance-pay'){paymentModal(false,key);return;}
 if(action==='expense-proof'){const image=await store.getExpenseProof(key);if(!image)throw Error('Vendor receipt unavailable.');modal('Vendor receipt',`<img src="${escape(image)}" style="max-width:100%;max-height:70vh;object-fit:contain" alt="Vendor receipt">`,null);return;}
 if(action==='period'){const p=policy(data,period());modal('Committee rate / closure decision',`${field('Selected month','month','month',period(),'required')}${field('Monthly base (RM)','monthly','number',p.monthly/100,'required min="0" max="100000" step="0.01"')}${field('Attendance rate (RM)','attendance','number',p.attendance/100,'required min="0" max="100000" step="0.01"')}<label class="check"><input type="checkbox" name="closed" ${p.closed?'checked':''}>Club closed for this month</label>${field('Meeting / decision / reason to share with members','reason','text',p.reason,'required maxlength="300"')}<p class="form-help">Rates apply from this month until superseded. Closure applies only to this month, blocks new sessions and fees, and marks existing sessions closed. Existing issued fees remain unchanged; correct those explicitly if required.</p>`,d=>store.savePeriod(d.month,{monthly:money(d.monthly,true),attendance:money(d.attendance,true),closed:Boolean(d.closed),reason:d.reason}));return;}
 if(action==='expense'){modal('Record paid expense',`${select('Category','category',['Courts','Shuttlecocks','Tournament','Friendly match','Equipment','Other'].map(x=>[x,x]),'Courts')}${field('Description','description','text','','required maxlength="200"')}${field('Amount (RM)','amount','number','','required min="0.01" max="100000" step="0.01"')}${field('Date paid','date','date',today(),`required max="${today()}"`)}${field('Supplier receipt / reference','reference','text','','maxlength="100"')}<label>Vendor receipt (optional)<input name="proof" type="file" accept="image/png,image/jpeg,image/webp"></label><img id="proof-preview" hidden style="max-width:100%;max-height:280px;object-fit:contain" alt="Vendor receipt preview">`,async d=>{const {proof,...entry}=d;return store.addExpense({...entry,amount:money(d.amount)},await store.compressProof(proof));});bindProofPreview();return;}
 if(action==='approve'){const s=data.submissions.find(x=>x.id===key);modal('Verify received payment',`<p>${who(s.uid)} · ${RM(s.amount)} · ${escape(s.reference)}</p>${s.proofId?`<button type="button" data-action="proof-inline" data-id="${escape(s.proofId)}">View screenshot</button><div id="proof-inline"></div>`:''}<label class="check"><input type="checkbox" required>I matched the amount and reference against bank or cash records, including checking for a duplicate transfer.</label>`,()=>store.recordPayment({uid:s.uid,bucket:s.bucket,amount:s.amount,date:s.date,reference:s.reference,method:s.method,guestName:s.guestName||'',attendanceId:s.attendanceId||''},key),'Verify received');return;}
 if(action==='reject'){modal('Reject payment',field('Reason','reason','text','','required maxlength="300"'),d=>store.rejectSubmission(key,d.reason),'Reject');return;}
 if(action==='proof'||action==='proof-inline'){const img=await store.getProof(key);if(!img)throw Error('Screenshot not available.');const html=`<img src="${escape(img)}" style="max-width:100%;max-height:70vh;object-fit:contain" alt="Payment confirmation screenshot">`;if(action==='proof-inline')document.querySelector('#proof-inline').innerHTML=html;else modal('Private payment screenshot',html,null);return;}
 if(action==='reverse-payment'||action==='reverse-expense'){modal('Reverse incorrect entry',`<p>The original is retained; totals for its receipt/payment month are restated.</p>${field('Reason','reason','text','','required maxlength="300"')}`,d=>store.reverseEntry(action==='reverse-payment'?'payments':'expenses',key,d.reason),'Confirm reversal');return;}
 if(action==='opening'){modal('Record opening balance',`${field('Year','year','number',year,'required min="2000" max="2100"')}${select('Account','uid',[['club','Club cash / bank opening'],...data.members.map(m=>[m.id,m.name+' · monthly account'])],'club')}${field('Signed amount (RM)','amount','number','0','required min="-100000" max="100000" step="0.01"')}${field('Source / reason','reason','text','','required maxlength="300"')}<p class="form-help">Member opening: positive = credit; negative = arrears. Use for initial migration only. Later years carry forward automatically; do not enter a second opening unless intentionally replacing the prior history baseline.</p>`,d=>store.saveOpening(d.year,d.uid,signedMoney(d.amount),d.reason));return;}
 if(action==='year-lock'){modal('Financial year control',`${field('Year','year','number',year,'required min="2000" max="2100"')}${select('Action','state',[['closed','Close year after reconciliation'],['open','Reopen for corrections']],'closed')}<p class="form-help">Records remain available across all years. Reopening and correcting a prior year can alter later opening balances. Review and republish affected statements.</p>`,d=>store.yearLock(d.year,d.state==='closed'));return;}
 if(action==='publish'){const snapshot=statement(data,year,through);modal('Preview member publication',`${statementHTML(snapshot)}<label class="check"><input type="checkbox" required>I approve sharing these named member balances and monthly totals with all active members. No payment references, screenshots or club opening funds are included.</label>`,()=>store.publishStatement(year,through,data),'Publish to members');dialog.classList.add('wide-dialog');return;}
 if(action==='schedule-month'){modal('Monthly court schedule',`${field('Month','month','month',period(),'required')}${field('Venue','venue','text','','required maxlength="160"')}${field('Courts','courts','text','','required maxlength="60"')}<p>Creates Monday and Wednesday sessions, 21:00–23:00 Malaysia time. Existing generated sessions are skipped. You still need to confirm the booking with the venue.</p>`,d=>store.generateSessions(d.month,d.venue,d.courts,data),'Create schedule');return;}
 if(action==='stock'){modal('Record shuttle stock',`${select('Movement','kind',['Opening stock','Purchase','Used','Adjustment in','Adjustment out'].map(x=>[x,x]),'Purchase')}${field('Date','date','date',today(),'required')}${field('Quantity (individual shuttlecocks)','quantity','number','','required min="1" max="10000" step="1"')}${field('Notes / tubes / supplier reference','notes','text','','required maxlength="300"')}<p class="form-help">A tube of 12 means quantity 12. Record purchases here for stock, and separately as paid expenses under finance.</p>`,d=>store.stockMovement({...d,quantity:Number(d.quantity)*(['Used','Adjustment out'].includes(d.kind)?-1:1)}));return;}
 if(action==='receipt'){const p=data.payments.find(p=>p.id===key);modal('Payment acknowledgement',`<div class="receipt"><h2>Santai Badminton Club</h2><p>${p.voidedAt?'REVERSED · NOT A VALID RECEIPT':store.isDemo()?'DEMONSTRATION RECEIPT':'PAYMENT ACKNOWLEDGEMENT'}</p><p>${who(p.uid)} · ${dateLabel(p.date)}</p><h1>${RM(p.amount)}</h1><p>${escape(p.method)}<br>${escape(p.reference)}</p><small>Record ID: ${escape(p.id)}</small><br><button type="button" data-action="print">Print / save PDF</button></div>`,null);return;}
 if(action==='print'){window.print();return;}
 if(action==='export-own'){download('Santai-my-payments-'+year+'.csv',csv([['Date','Account','Reference','RM','Status'],...data.payments.filter(p=>p.uid===user.id&&within(p)).map(p=>[p.date,bucket(p),p.reference,p.amount/100,p.voidedAt?'Reversed':'Verified'])]));return;}
 if(action==='export-statement'){const s=data.publications.find(p=>p.year===year&&p.month===through);download('Santai-Print-'+period()+'.csv',csv([['Member','Opening credit/arrears RM','Issued RM','Paid RM','Balance RM'],...s.rows.map(r=>[r.name,r.opening/100,r.assessed/100,r.paid/100,r.balance/100])]));return;}
 if(action==='backup'){const d=await store.fullBackup();download('Santai-private-backup-'+today()+'.json',JSON.stringify({version:'1.2',exportedAt:new Date().toISOString(),...d},null,2),'application/json');return;}
 }catch(err){formError(err);}}
dialog.addEventListener('close',()=>dialog.classList.remove('wide-dialog'));
store.init(async u=>{user=u;if(!u){loginScreen();return;}if(!u.verified||u.status!=='active'){waiting(u);return;}try{await refresh();}catch(e){app.innerHTML=`<main class="loading"><h1>Unable to load club records</h1><p>${escape(e.message)}</p><button data-action="logout">Sign out</button></main>`;}}).catch(e=>{loginScreen();toast('Firebase connection failed. '+e.message);});
